    # several neighboring markers are not treated as drawn segments.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 4:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 4:
                c += 1
            if a > 0 and c < w and grid[r][a - 1] == 9 and grid[r][c] == 9:
                left_marks = sum(v == 9 for v in grid[r][:a])
                right_marks = sum(v == 9 for v in grid[r][c + 1:])
                if c - a >= 2 or left_marks == 1 or right_marks == 1:
                    for x in range(a, c):
                        out[r][x] = 2

